package in.sevasetu.amc.web;
import jakarta.validation.Valid;import jakarta.validation.constraints.*;import org.springframework.http.*;import org.springframework.jdbc.core.simple.JdbcClient;import org.springframework.security.access.prepost.PreAuthorize;import org.springframework.security.crypto.password.PasswordEncoder;import org.springframework.transaction.annotation.Transactional;import org.springframework.web.bind.annotation.*;import org.springframework.web.server.ResponseStatusException;import java.time.LocalDate;import java.util.*;
@RestController @RequestMapping("/api/admin/tenants") @PreAuthorize("hasRole('ADMIN')") public class AdminTenantController{private final JdbcClient db;private final PasswordEncoder passwords;public AdminTenantController(JdbcClient db,PasswordEncoder passwords){this.db=db;this.passwords=passwords;}public record BranchInput(@NotBlank String code,@NotBlank String name,String address,String phone){}public record Create(@NotBlank String code,@NotBlank String name,@NotBlank String domain,@NotBlank String themeKey,@NotEmpty List<@Valid BranchInput> branches,@NotBlank String ownerName,@NotBlank String ownerUsername,@Size(min=8)String ownerPassword){}public record Tenant(UUID id,String code,String name,String domain,String themeKey,long branches,long employees){}
 @GetMapping List<Tenant> list(){return db.sql("select t.id,t.code,t.name,t.domain,t.theme_key,(select count(*) from amcservice.branches b where b.tenant_id=t.id),(select count(*) from amcservice.employees e where e.tenant_id=t.id) from amcservice.tenants t order by t.name").query((rs,n)->new Tenant(rs.getObject(1,UUID.class),rs.getString(2),rs.getString(3),rs.getString(4),rs.getString(5),rs.getLong(6),rs.getLong(7))).list();}
 @PostMapping @ResponseStatus(HttpStatus.CREATED) @Transactional Tenant create(@Valid @RequestBody Create r){var tenantId=UUID.randomUUID();try{db.sql("insert into amcservice.tenants(id,code,name,domain,theme_key) values(:id,:code,:name,:domain,:theme)").param("id",tenantId).param("code",r.code().toUpperCase(Locale.ROOT)).param("name",r.name()).param("domain",r.domain().toUpperCase(Locale.ROOT)).param("theme",r.themeKey()).update();}catch(Exception e){throw new ResponseStatusException(HttpStatus.CONFLICT,"Company code or owner user ID already exists");}UUID firstBranch=null;for(var branch:r.branches()){var id=UUID.randomUUID();if(firstBranch==null)firstBranch=id;db.sql("insert into amcservice.branches(id,tenant_id,code,name,address,phone) values(:id,:t,:code,:name,:address,:phone)").param("id",id).param("t",tenantId).param("code",branch.code().toUpperCase(Locale.ROOT)).param("name",branch.name()).param("address",branch.address()).param("phone",branch.phone()).update();}var userId=UUID.randomUUID();var employeeId=UUID.randomUUID();db.sql("insert into amcservice.users(id,tenant_id,branch_id,username,password_hash,display_name,role) values(:id,:t,:b,:username,:password,:name,'OWNER')").param("id",userId).param("t",tenantId).param("b",firstBranch).param("username",r.ownerUsername()).param("password",passwords.encode(r.ownerPassword())).param("name",r.ownerName()).update();db.sql("insert into amcservice.employees(id,tenant_id,branch_id,user_id,name,employee_type,job_role,date_of_joining) values(:id,:t,:b,:u,:name,'OWNER','OWNER',:joining)").param("id",employeeId).param("t",tenantId).param("b",firstBranch).param("u",userId).param("name",r.ownerName()).param("joining",LocalDate.now()).update();db.sql("update amcservice.users set employee_id=:e where id=:u").param("e",employeeId).param("u",userId).update();return new Tenant(tenantId,r.code().toUpperCase(Locale.ROOT),r.name(),r.domain().toUpperCase(Locale.ROOT),r.themeKey(),r.branches().size(),1);}
}
